50	// Workspace name validation constants (must match backend: mlflow/store/workspace/abstract_store.py)
51	export const WORKSPACE_NAME_PATTERN = /^(?!.*--)[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;
52	export const WORKSPACE_NAME_MIN_LENGTH = 2;
53	export const WORKSPACE_NAME_MAX_LENGTH = 63;
54	
55	export type WorkspaceValidationResult = {
56	  valid: boolean;
57	  error?: string;
58	};
59	
60	/** Validates workspace name against backend rules. Reserved names checked by API. */
61	export const validateWorkspaceName = (name: string): WorkspaceValidationResult => {
62	  if (typeof name !== 'string') {
63	    return { valid: false, error: 'Workspace name must be a string.' };
64	  }
65	
66	  if (name.length < WORKSPACE_NAME_MIN_LENGTH || name.length > WORKSPACE_NAME_MAX_LENGTH) {
67	    return {
68	      valid: false,
69	      error: `Workspace name must be between ${WORKSPACE_NAME_MIN_LENGTH} and ${WORKSPACE_NAME_MAX_LENGTH} characters.`,
70	    };
71	  }
72	
73	  if (!WORKSPACE_NAME_PATTERN.test(name)) {
74	    return {
75	      valid: false,
76	      error: 'Workspace name must be lowercase alphanumeric with optional single hyphens (no consecutive hyphens).',
77	    };
78	  }
79	
80	  return { valid: true };
81	};
82	
83	/** Extract and validate workspace from URL search params. */
84	export const extractWorkspaceFromSearchParams = (search: string | URLSearchParams): string | null => {
85	  const params = typeof search === 'string' ? new URLSearchParams(search) : search;
86	  const workspaceName = params.get(WORKSPACE_QUERY_PARAM);
87	
88	  if (!workspaceName || !WORKSPACE_NAME_PATTERN.test(workspaceName)) {
89	    return null;
90	  }
91	
92	  return workspaceName;
93	};
94	
95	const isAbsoluteUrl = (value: string) => /^[a-zA-Z][a-zA-Z\d+\-.]*:/.test(value);
96	
97	/**
98	 * Routes that never have workspace context. Root '/' is contextual.
99	 * Kept as an extension point for any future workspace-agnostic routes.
100	 */
101	const ALWAYS_GLOBAL_ROUTES: string[] = [];
102	
103	/** Check if pathname is always global (workspace-agnostic). */
104	export const isGlobalRoute = (pathname: string): boolean => {
105	  const normalizedPath = pathname.split('?')[0].split('#')[0];
106	  return ALWAYS_GLOBAL_ROUTES.some((route) => normalizedPath === route || normalizedPath.startsWith(route + '/'));
107	};
108	
109	/** Add workspace query param to URL, preserving existing params and hash. */
110	const addWorkspaceQueryParam = (url: string, workspace: string): string => {
111	  const hashPrefix = url.startsWith('#') ? '#' : '';
112	  const urlWithoutHashPrefix = hashPrefix ? url.slice(1) : url;
113	
114	  let pathname = urlWithoutHashPrefix;
115	  let existingQuery = '';
116	  let hashFragment = '';
117	
118	  const hashIndex = pathname.indexOf('#');
119	  if (hashIndex >= 0) {
120	    hashFragment = pathname.slice(hashIndex);
121	    pathname = pathname.slice(0, hashIndex);
122	  }
123	
124	  const queryIndex = pathname.indexOf('?');
125	  if (queryIndex >= 0) {
126	    existingQuery = pathname.slice(queryIndex + 1);
127	    pathname = pathname.slice(0, queryIndex);
128	  }
129	
130	  const params = new URLSearchParams(existingQuery);
131	  params.set(WORKSPACE_QUERY_PARAM, workspace);
132	
133	  return `${hashPrefix}${pathname}?${params.toString()}${hashFragment}`;
134	};
135	
136	/** Remove workspace query param from URL. */
137	export const removeWorkspaceQueryParam = (url: string): string => {
138	  const hashPrefix = url.startsWith('#') ? '#' : '';
139	  const urlWithoutHashPrefix = hashPrefix ? url.slice(1) : url;
140	
141	  let pathname = urlWithoutHashPrefix;
142	  let existingQuery = '';
143	  let hashFragment = '';
144	
145	  const hashIndex = pathname.indexOf('#');
146	  if (hashIndex >= 0) {
147	    hashFragment = pathname.slice(hashIndex);
148	    pathname = pathname.slice(0, hashIndex);
149	  }
150	
151	  const queryIndex = pathname.indexOf('?');
152	  if (queryIndex >= 0) {
153	    existingQuery = pathname.slice(queryIndex + 1);
154	    pathname = pathname.slice(0, queryIndex);
155	  }
156	
157	  const params = new URLSearchParams(existingQuery);
158	  params.delete(WORKSPACE_QUERY_PARAM);
159	
160	  const queryString = params.toString();
161	  return `${hashPrefix}${pathname}${queryString ? '?' + queryString : ''}${hashFragment}`;
162	};
163	
164	/**
165	 * Prefix route with workspace query param. Removes workspace from global routes.
166	 * Relative paths unchanged. Root '/' is contextual based on workspace param.
167	 */
168	export const prefixRouteWithWorkspace = (to: string): string => {
169	  if (typeof to !== 'string' || to.length === 0) {
170	    return to;
171	  }
172	
173	  if (!getWorkspacesEnabledSync() || isAbsoluteUrl(to)) {
174	    return to;
175	  }
176	
177	  const hashPrefix = to.startsWith('#') ? '#' : '';
178	  const urlWithoutHashPrefix = hashPrefix ? to.slice(1) : to;
179	
180	  const isAbsoluteNavigation = hashPrefix !== '' || urlWithoutHashPrefix.startsWith('/');
181	  if (!isAbsoluteNavigation) {
182	    return to;
183	  }
184	
185	  let pathname = urlWithoutHashPrefix;
186	  let existingQuery = '';
187	  const hashIndex = pathname.indexOf('#');
188	  if (hashIndex >= 0) {
189	    pathname = pathname.slice(0, hashIndex);
190	  }
191	  const queryIndex = pathname.indexOf('?');
192	  if (queryIndex >= 0) {
193	    existingQuery = pathname.slice(queryIndex + 1);
194	    pathname = pathname.slice(0, queryIndex);
195	  }
196	
197	  const existingParams = new URLSearchParams(existingQuery);
198	  const hasExplicitWorkspace = existingParams.has(WORKSPACE_QUERY_PARAM);
199	
200	  if (isGlobalRoute(pathname || '/')) {
201	    return removeWorkspaceQueryParam(to);
202	  }
203	
204	  if (hasExplicitWorkspace) {
205	    return to;
206	  }
207	
208	  const workspace = getActiveWorkspace();
209	  if (!workspace) {
210	    return to;
211	  }
212	
213	  return addWorkspaceQueryParam(to, workspace);
214	};
215	
216	/** Prefix pathname with workspace query param. Similar to prefixRouteWithWorkspace. */
217	export const appendWorkspaceSearchParams = (pathname: string | undefined): string | undefined => {
218	  if (!pathname) {
219	    return pathname;
220	  }
221	  if (!getWorkspacesEnabledSync() || isAbsoluteUrl(pathname)) {
222	    return pathname;
