1	import { Component } from 'react';
2	import errorDefaultImg from '../static/default-error.svg';
3	import error404Img from '../static/404-overflow.svg';
4	import Routes from '../../experiment-tracking/routes';
5	import { Link } from '../utils/RoutingUtils';
6	import { FormattedMessage } from 'react-intl';
7	import type { DesignSystemHocProps } from '@databricks/design-system';
8	import { WithDesignSystemThemeHoc } from '@databricks/design-system';
