10	const altMessages: Record<number, string> = {
11	  400: '400 Bad Request',
12	  401: '401 Unauthorized',
13	  404: '404 Not Found',
14	  409: '409 Conflict',
15	  500: '500 Internal Server Error',
16	  502: '502 Bad Gateway',
17	  503: '503 Service Unavailable',
18	};
19	
20	type ErrorImageProps = {
21	  statusCode: number;
22	};
23	
24	function ErrorImage(props: ErrorImageProps) {
25	  const { statusCode } = props;
26	  const alt = altMessages[statusCode] || statusCode.toString();
27	
28	  switch (props.statusCode) {
29	    case 404:
30	      return (
31	        <img className="mlflow-center" alt={alt} style={{ height: '300px', marginTop: '80px' }} src={error404Img} />
32	      );
33	    default:
34	      return (
35	        <img
36	          className="mlflow-center"
37	          alt={alt}
38	          src={errorDefaultImg}
39	          style={{
40	            margin: '12% auto 60px',
41	            display: 'block',
42	          }}
43	        />
44	      );
45	  }
46	}
47	
48	type ErrorViewImplProps = DesignSystemHocProps & {
49	  statusCode: number;
50	  subMessage?: string;
51	  fallbackHomePageReactRoute?: string;
52	};
53	
54	class ErrorViewImpl extends Component<ErrorViewImplProps> {
55	  static centerMessages: Record<number, string> = {
56	    400: 'Bad Request',
57	    404: 'Page Not Found',
58	    409: 'Resource Conflict',
59	  };
60	
61	  renderErrorMessage(subMessage?: string, fallbackHomePageReactRoute?: string) {
62	    if (subMessage) {
63	      return (
64	        <FormattedMessage
65	          defaultMessage="{subMessage}, go back to <link>the home page.</link>"
66	          description="Default error message for error views in MLflow"
67	          values={{
68	            link: (chunks) => (
69	              <Link
70	                data-testid="error-view-link"
71	                componentId="mlflow.common.error_view.fallback_link"
72	                to={fallbackHomePageReactRoute || Routes.rootRoute}
73	              >
74	                {chunks}
75	              </Link>
76	            ),
77	            subMessage: subMessage,
78	          }}
79	        />
80	      );
81	    } else {
82	      return (
83	        <FormattedMessage
84	          defaultMessage="Go back to <link>the home page.</link>"
85	          description="Default error message for error views in MLflow"
86	          values={{
87	            link: (chunks) => (
88	              <Link
89	                data-testid="error-view-link"
90	                componentId="mlflow.common.error_view.fallback_link"
91	                to={fallbackHomePageReactRoute || Routes.rootRoute}
92	              >
93	                {chunks}
94	              </Link>
95	            ),
96	          }}
97	        />
98	      );
99	    }
100	  }
101	
102	  render() {
103	    const { statusCode, subMessage, fallbackHomePageReactRoute, designSystemThemeApi } = this.props;
104	    const centerMessage = ErrorViewImpl.centerMessages[statusCode] || 'HTTP Request Error';
105	
106	    return (
107	      <div className="mlflow-center">
108	        <ErrorImage statusCode={statusCode} />
109	        <h1 style={{ paddingTop: '10px' }}>{centerMessage}</h1>
110	        <h2 style={{ color: designSystemThemeApi.theme.colors.textSecondary }}>
111	          {this.renderErrorMessage(subMessage, fallbackHomePageReactRoute)}
112	        </h2>
113	      </div>
114	    );
115	  }
116	}
117	
118	export const ErrorView = WithDesignSystemThemeHoc(ErrorViewImpl);
