1	import React, { useState } from 'react';
2	import { Header, HomeIcon, TableSkeleton, TitleSkeleton, useDesignSystemTheme } from '@databricks/design-system';
3	import { FormattedMessage } from 'react-intl';
4	import { ScrollablePageWrapper } from '../common/components/ScrollablePageWrapper';
5	import { useQuery } from '@mlflow/mlflow/src/common/utils/reactQueryHooks';
6	import { MlflowService } from '../experiment-tracking/sdk/MlflowService';
7	import type { SearchExperimentsApiResponse } from '../experiment-tracking/types';
8	import { CreateExperimentModal } from '../experiment-tracking/components/modals/CreateExperimentModal';
9	import { useInvalidateExperimentList } from '../experiment-tracking/components/experiment-page/hooks/useExperimentListQuery';
10	import { FeaturesSection } from './components/features';
11	// Loaders and lazy imports for expensive components
12	import LogTracesDrawerLoader from './components/LogTracesDrawerLoader';
13	import { TelemetryInfoAlert } from '../telemetry/TelemetryInfoAlert';
14	
15	const ExperimentsHomeView = React.lazy(() => import('./components/ExperimentsHomeView'));
